-- TASK-0065 Open Hand teaching items: ap-calculus-bc (8 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'ap-calculus-bc';
  v_tsv uuid := 'ab088009-dc9a-4f93-8824-803e1913505b';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"apcalcbc-oht-1.1","topic_code":"1.1","title":"Introducing Calculus: Can Change Occur at an Instant?","stem":"A moving object's position at time t seconds is s(t) meters. Assume its instantaneous rate of change at t = 5 exists. Which procedure defines this instantaneous rate, rather than an average rate over a fixed interval?","choices":[{"choice_key":"A","choice_text":"Evaluate (s(5)−s(5))/(5−5).","is_correct":false,"rationale":"Zero-interval substitution attempts to use an average-rate quotient at a single instant. This gives 0/0, which is undefined, not an instantaneous rate. Fix: Use nonzero time intervals and consider what their average rates approach."},{"choice_key":"B","choice_text":"Compute (s(6)−s(4))/(6−4).","is_correct":false,"rationale":"Fixed-interval confusion substitutes an average rate around the instant for the instantaneous rate. This quotient describes the entire interval from 4 to 6 seconds, even if it happens to equal the instantaneous rate. Fix: Shrink the interval toward t = 5 instead of keeping its endpoints fixed."},{"choice_key":"C","choice_text":"Divide the position s(5) by the elapsed time 5.","is_correct":false,"rationale":"Position-versus-change confusion treats position divided by time as an instantaneous rate. The quotient s(5)/5 does not generally measure even an average rate unless the initial position is zero. Fix: Compute position changes over shrinking time intervals, rather than dividing position by time."},{"choice_key":"D","choice_text":"Find the value approached by average rates over nonzero time intervals containing t = 5 as those intervals shrink toward t = 5.","is_correct":true,"rationale":"Average rates describe position change over time intervals. The instantaneous rate is the value these average rates approach as the intervals shrink toward the single instant."}]},{"content_key":"apcalcbc-oht-1.16","topic_code":"1.16","title":"Working with the Intermediate Value Theorem","stem":"Let f be a polynomial with f(1) = 2 and f(5) = 8. Which statement is guaranteed by the Intermediate Value Theorem?","choices":[{"choice_key":"A","choice_text":"There is at least one c in (1,5) such that f(c) = 5.","is_correct":true,"rationale":"Polynomials are continuous on [1,5], and 2 < 5 < 8. The Intermediate Value Theorem therefore guarantees at least one c in (1,5) with f(c) = 5."},{"choice_key":"B","choice_text":"There is exactly one c in (1,5) such that f(c) = 5.","is_correct":false,"rationale":"Existence-versus-uniqueness error: the theorem guarantees that f reaches 5, but a polynomial can reach that value more than once. Fix: Check whether the theorem guarantees existence or also guarantees uniqueness."},{"choice_key":"C","choice_text":"f(3) = 5.","is_correct":false,"rationale":"Midpoint interpolation error: averaging the endpoint inputs and outputs assumes a linear relationship that is not given. The theorem guarantees an input where f equals 5, not its exact location. Fix: Distinguish an existence conclusion from a claim about a specific input."},{"choice_key":"D","choice_text":"There is at least one c in (1,5) such that f(c) = 10.","is_correct":false,"rationale":"Target-value condition error: 10 lies outside [2,8], so the given endpoint values do not guarantee that f reaches 10 inside the interval. Fix: Compare the target value with both endpoint outputs before applying the theorem."}]},{"content_key":"apcalcbc-oht-1.3","topic_code":"1.3","title":"Estimating Limit Values from Graphs","stem":"The graph of f is described as follows: As x approaches 3 from the left, the graph approaches an open circle at (3, 2). As x approaches 3 from the right, the graph approaches an open circle at (3, 6). A filled point is located at (3, 4). What is lim x→3 f(x)?","choices":[{"choice_key":"A","choice_text":"2","is_correct":false,"rationale":"Left-side-only error: This uses the value approached by the left branch but ignores the right branch, which approaches 6. Fix: Trace both branches toward the input and compare their approached values."},{"choice_key":"B","choice_text":"The limit does not exist.","is_correct":true,"rationale":"The graph approaches 2 from the left and 6 from the right. A two-sided limit requires the same value from both sides, so the unequal one-sided limits mean this limit does not exist."},{"choice_key":"C","choice_text":"6","is_correct":false,"rationale":"Right-side-only error: This uses the value approached by the right branch but ignores the left branch, which approaches 2. Fix: Check the left-hand behavior before concluding that a two-sided limit exists."},{"choice_key":"D","choice_text":"4","is_correct":false,"rationale":"Function-value confusion: The filled point gives f(3) = 4, not the value approached nearby. The two branches approach different heights, so the filled point cannot determine this limit. Fix: Trace the nearby branches from both sides before looking at the filled point."}]},{"content_key":"apcalcbc-oht-1.7","topic_code":"1.7","title":"Selecting Procedures for Determining Limits","stem":"Which procedure is appropriate for determining lim x→2 |x−2|/(x−2)?","choices":[{"choice_key":"A","choice_text":"Replace |x−2| with x−2 on both sides of 2, then cancel to obtain a limit of 1.","is_correct":false,"rationale":"Absolute-value removal error: |x−2| equals x−2 only when x ≥ 2. For x < 2, |x−2| = −(x−2), so this cancellation ignores the left-hand behavior. Fix: Write the absolute-value expression separately for x < 2 and x > 2."},{"choice_key":"B","choice_text":"Check the left-hand and right-hand limits separately, using the appropriate expression for |x−2| on each side.","is_correct":true,"rationale":"The absolute value requires different expressions on the two sides of 2. For x < 2, the quotient is −1; for x > 2, it is 1, so the unequal one-sided limits show that the two-sided limit does not exist."},{"choice_key":"C","choice_text":"Use direct substitution and interpret 0/0 as a limit of 0.","is_correct":false,"rationale":"Indeterminate-form error: 0/0 is not a number and does not determine the limit. Direct substitution therefore does not resolve this problem. Fix: When substitution gives 0/0, examine the expression for nearby inputs."},{"choice_key":"D","choice_text":"Use the denominator’s approach to 0 to conclude that the limit is ∞.","is_correct":false,"rationale":"Zero-denominator shortcut: a denominator approaching 0 does not by itself imply an infinite limit. Here, the numerator also approaches 0, and the quotient remains either −1 or 1 for x ≠ 2. Fix: Check the numerator and simplify the quotient on each side before concluding infinite behavior."}]},{"content_key":"apcalcbc-oht-1.9","topic_code":"1.9","title":"Connecting Multiple Representations of Limits","stem":"A graph of y = f(x) has an open circle at (2, 5) and a filled point at (2, 8). As x approaches 2 from either side, the graph approaches the open circle. Which limit statement matches this graphical description?","choices":[{"choice_key":"A","choice_text":"lim x→2 f(x) = 8","is_correct":false,"rationale":"Function-value confusion uses the filled point’s height as the limit. The filled point gives f(2) = 8, but nearby graph values approach 5. Fix: Follow the graph from both sides instead of using the filled point."},{"choice_key":"B","choice_text":"lim x→2 f(x) = 5","is_correct":true,"rationale":"From both sides of x = 2, the graph’s y-values approach 5. Thus, the graphical description translates to: as x approaches 2, f(x) approaches 5, regardless of the filled point’s height."},{"choice_key":"C","choice_text":"lim x→2 f(x) = 2","is_correct":false,"rationale":"Input-output confusion uses the approaching x-value as the limit of f(x). Here, 2 is the input being approached, while 5 is the output being approached. Fix: Identify the approached x-coordinate and y-coordinate separately before writing the limit."},{"choice_key":"D","choice_text":"lim x→2 f(x) does not exist","is_correct":false,"rationale":"Open-circle confusion treats a hole as preventing a limit from existing. A limit describes nearby behavior, and the graph approaches the same height from both sides. Fix: Compare the approached heights on both sides before deciding whether the limit exists."}]},{"content_key":"apcalcbc-oht-2.3","topic_code":"2.3","title":"Estimating Derivatives of a Function at a Point","stem":"A cup of tea is cooling. The table gives its temperature T(t), in degrees Celsius, at selected times t, in minutes. t: 0, 2, 5, 6, 9. T(t): 70, 64, 58, 55, 49. Using the data at the nearest table times on either side of t = 5, which is the best estimate of T′(5)?","choices":[{"choice_key":"A","choice_text":"−7/3 °C per minute","is_correct":false,"rationale":"This uses the distant endpoints t = 0 and t = 9, giving (49 − 70)/9, the average rate over the whole table. Values far from t = 5 describe the overall trend, not the local rate at t = 5. Fix: Pick the table values closest to the target time on each side before computing the slope."},{"choice_key":"B","choice_text":"−9 °C per minute","is_correct":false,"rationale":"This finds the temperature change 55 − 64 but never divides by the elapsed time of 4 minutes. A change in temperature is measured in °C, not °C per minute, so it is not a rate. Fix: Divide the output change by the input change and check that the units read °C per minute."},{"choice_key":"C","choice_text":"−2.25 °C per minute","is_correct":true,"rationale":"The nearest times bracketing t = 5 are t = 2 and t = 6, so T′(5) ≈ (55 − 64)/(6 − 2) = −9/4 = −2.25. This difference quotient is a local slope estimate in °C per minute, not an exact derivative value."},{"choice_key":"D","choice_text":"2.25 °C per minute","is_correct":false,"rationale":"This is a sign error from subtracting temperatures and times in opposite orders, such as (64 − 55)/(6 − 2). The temperature is falling between t = 2 and t = 6, so the rate must be negative. Fix: Subtract outputs and inputs in the same order, then check whether the sign matches increasing or decreasing data."}]},{"content_key":"apcalcbc-oht-2.6","topic_code":"2.6","title":"Derivative Rules: Constant, Sum, Difference, and Constant Multiple","stem":"Let g and h be differentiable functions with g′(2) = 5 and h′(2) = −2. Define f(x) = 4g(x) − 3h(x) + 7. What is f′(2)?","choices":[{"choice_key":"A","choice_text":"33","is_correct":false,"rationale":"Constant-retention error: adding 7 to the derivative gives 33, but the derivative of a constant is 0. Fix: Replace each constant term with 0 before evaluating the derivative."},{"choice_key":"B","choice_text":"14","is_correct":false,"rationale":"Sign error: subtracting 3h′(2) means subtracting −6, not subtracting 6. The subtraction sign in f remains when differentiating. Fix: Substitute negative derivative values in parentheses before simplifying signs."},{"choice_key":"C","choice_text":"26","is_correct":true,"rationale":"Differentiate term by term, preserving each coefficient and subtraction sign; the constant 7 has derivative 0. Thus f′(2) = 4g′(2) − 3h′(2) = 4(5) − 3(−2) = 26."},{"choice_key":"D","choice_text":"7","is_correct":false,"rationale":"Constant-multiple error: 5 − (−2) = 7 omits the coefficients 4 and 3. These coefficients must multiply the corresponding derivatives. Fix: Copy each coefficient beside its function’s derivative before substituting values."}]},{"content_key":"apcalcbc-oht-3.6","topic_code":"3.6","title":"Calculating Higher-Order Derivatives","stem":"Let f(x) = x⁴ − 3x³ + 2x. What is f″(2)?","choices":[{"choice_key":"A","choice_text":"12","is_correct":true,"rationale":"Differentiate twice: f′(x) = 4x³ − 9x² + 2 and f″(x) = 12x² − 18x. Then f″(2) = 48 − 36 = 12."},{"choice_key":"B","choice_text":"−2","is_correct":false,"rationale":"Stopping after one derivative gives f′(2) = −2, not f″(2). The double prime requires differentiating the original function twice. Fix: Write f′(x), then differentiate it before substituting x = 2."},{"choice_key":"C","choice_text":"30","is_correct":false,"rationale":"Differentiating one time too many gives f‴(x) = 24x − 18 and f‴(2) = 30. The question asks for the second derivative, not the third. Fix: Count the primes and stop after that many differentiations."},{"choice_key":"D","choice_text":"0","is_correct":false,"rationale":"Substituting too early gives the constant f(2) = −4, whose derivatives are zero. Differentiating this constant does not compute the derivatives of f at x = 2. Fix: Differentiate the function twice before evaluating at x = 2."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_09',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 BC+Precalculus Units 1-3 2026-10-09')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 BC+Precalculus Units 1-3 2026-10-09'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
